// OIDDispatch returns a shallow copy of the package's wire-key →
// AnyColumn map. The copy isolates callers from accidental mutation
// of the package-internal map.
func OIDDispatch() map[string]snmp.AnyColumn {
	out := make(map[string]snmp.AnyColumn, len(eNTITYSTATEMIBOIDDispatch))
	for k, v := range eNTITYSTATEMIBOIDDispatch {
		out[k] = v
	}
	return out
}

// eNTITYSTATEMIBColumnTiers maps column wire keys ([snmp.OID.WireKey]) to their
// snmp.Tier classification.
// Tier classification drives the Watcher's scheduler — counters fire
// on their own cadence, state columns refresh on indicator advance,
// and indicator columns drive the change-detection probe itself.
// See snmp.Tier and snmp.Watcher for the consumption contract.
var eNTITYSTATEMIBColumnTiers = map[string]snmp.Tier{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 1).WireKey(): snmp.TierIndicator,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 2).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 3).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 4).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 5).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 131, 1, 1, 1, 6).WireKey(): snmp.TierState,
}

// ColumnTier returns the codegen-classified [snmp.Tier] for col, or
// snmp.TierUnknown when col's OID is not known to this package. The
// generated Watch methods install this function via
// [snmp.WithTierLookup]; returning TierUnknown lets the runtime fall
// back to its wire-Kind heuristic for columns this package does not
// classify. Caller overrides via [snmp.WithColumnTier] still win.
func ColumnTier(col snmp.AnyColumn) snmp.Tier {
	if col == nil {
		return snmp.TierUnknown
	}
	t, ok := eNTITYSTATEMIBColumnTiers[col.Key()]
	if !ok {
		return snmp.TierUnknown
	}
	return t
}

